// Прод: только GET через API request, без браузера и JS. Обход всех объявлений из sitemap, параллельно по 8.
import { test, expect, type APIRequestContext } from '@playwright/test';

const UA = 'WhatsApp/2.23.20.0 A';
const CONCURRENCY = 8;
const MAX_BYTES = 300 * 1024;

function decodeEntities(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(tag: string): Record<string, string> {
  const attrs: Record<string, string> = {};
  const re = /([^\s"'<>\/=]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(tag))) attrs[m[1].toLowerCase()] = decodeEntities(m[2] ?? m[3] ?? m[4] ?? '');
  return attrs;
}

function meta(html: string, key: string): string | undefined {
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    const a = parseAttrs(tag);
    if ((a['property'] === key || a['name'] === key) && 'content' in a) return a['content'].trim();
  }
  return undefined;
}

/** Ширина×высота из SOF-маркера JPEG; null — не JPEG или маркер не найден. */
function jpegSize(buf: Buffer): [number, number] | null {
  if (buf.length < 4 || buf[0] !== 0xff || buf[1] !== 0xd8) return null;
  let i = 2;
  while (i + 9 < buf.length) {
    if (buf[i] !== 0xff) { i++; continue; }
    const marker = buf[i + 1];
    if (marker === 0xff) { i++; continue; }
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) { i += 2; continue; }
    const len = buf.readUInt16BE(i + 2);
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      return [buf.readUInt16BE(i + 7), buf.readUInt16BE(i + 5)];
    }
    i += 2 + len;
  }
  return null;
}

type Row = {
  id: string; page: number; img?: string; status?: number; ctype?: string;
  size?: number; dims?: string; metaType?: string; metaW?: string; metaH?: string; problems: string[];
};

async function checkListing(request: APIRequestContext, id: string): Promise<Row> {
  const row: Row = { id, page: 0, problems: [] };
  const res = await request.get(`/b/${id.slice(0, 8)}`, { headers: { 'User-Agent': UA } });
  row.page = res.status();
  if (row.page !== 200) { row.problems.push(`страница ${row.page}`); return row; }
  const html = await res.text();
  row.img = meta(html, 'og:image');
  row.metaType = meta(html, 'og:image:type');
  row.metaW = meta(html, 'og:image:width');
  row.metaH = meta(html, 'og:image:height');
  if (row.metaType !== 'image/jpeg') row.problems.push(`og:image:type=${row.metaType}`);
  if (row.metaW !== '1200' || row.metaH !== '630') row.problems.push(`og:image:width/height=${row.metaW}×${row.metaH}`);
  if (!row.img) { row.problems.push('нет og:image'); return row; }

  const img = await request.get(row.img, { headers: { 'User-Agent': UA } });
  row.status = img.status();
  row.ctype = img.headers()['content-type'];
  const body = await img.body();
  row.size = body.length;
  const d = jpegSize(body);
  row.dims = d ? `${d[0]}×${d[1]}` : 'не JPEG';
  if (row.status !== 200) row.problems.push(`картинка ${row.status}`);
  if (!row.ctype?.includes('image/jpeg')) row.problems.push(`content-type=${row.ctype}`);
  if (row.size > MAX_BYTES) row.problems.push(`${Math.round(row.size / 1024)}KB > 300KB`);
  if (row.dims !== '1200×630') row.problems.push(`размер ${row.dims}`);
  return row;
}

test.describe('SEO техническая инфраструктура — og:image объявлений', () => {
  test('og:image всех объявлений из sitemap: JPEG 1200×630 ≤ 300KB, мета-теги размера верные #cada05 @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(10 * 60_000);

    // 1. Все объявления из sitemap
    const sm = await request.get('/sitemap.xml');
    expect(sm.status()).toBe(200);
    const ids = [...new Set([...(await sm.text()).matchAll(/businessdetail\?id=([0-9a-f-]{8,})/gi)].map((m) => m[1]))];
    expect(ids.length, 'объявления в sitemap').toBeGreaterThan(0);

    // 2–4. По 8 параллельно: /b/<код> → og:image → проверка
    const rows: Row[] = [];
    let next = 0;
    await Promise.all(
      Array.from({ length: CONCURRENCY }, async () => {
        while (next < ids.length) {
          const id = ids[next++];
          try {
            rows.push(await checkListing(request, id));
          } catch (e) {
            rows.push({ id, page: 0, problems: [`ошибка запроса: ${(e as Error).message.split('\n')[0]}`] });
          }
        }
      }),
    );

    const bad = rows.filter((r) => r.problems.length);
    const report = bad
      .map((r) => `${r.id}: ${r.problems.join('; ')} | img ${r.status ?? '-'} ${r.ctype ?? '-'} ${r.size ?? '-'}B ${r.dims ?? '-'} | meta ${r.metaType ?? '-'} ${r.metaW ?? '-'}×${r.metaH ?? '-'} | ${r.img ?? ''}`)
      .join('\n');
    const maxKB = Math.round(Math.max(0, ...rows.map((r) => r.size ?? 0)) / 1024);
    expect(bad, `нарушителей ${bad.length}/${rows.length} (max ${maxKB}KB):\n${report}`).toHaveLength(0);
  });
});
